      return ScanPriority(rawValue: Int(raw))
    case 130:
      guard let raw = readValue() as? Int64 else { return nil }
      return MessageSource(rawValue: Int(raw))
    case 131:
      guard let raw = readValue() as? Int64 else { return nil }
      return BluetoothState(rawValue: Int(raw))
    case 132:
